mapper.select:
SELECT
IF(bs.balance_direction='DEBIT',
IF(IFNULL(SUM(bvr.debit),0)=0,IFNULL(SUM(bvr.credit),0),IFNULL(SUM(bvr.debit),0)),
IF(IFNULL(SUM(bvr.credit),0)=0,IFNULL(SUM(bvr.debit),0),IFNULL(SUM(bvr.credit),0))
)
FROM `book_voucher_record` bvr
LEFT JOIN book_voucher bv on bv.voucher_id = bvr.voucher_id
LEFT JOIN book_subject bs on bvr.subject_id = bs.subject_id
LEFT JOIN book_carryover bc ON bv.type_class_id = bc.carryover_id
where bvr.del_flag = '0' and bv.del_flag = '0' and bv.book_id = #{bookId}
and bs.code LIKE CONCAT('',#{subjectCode} ,'%') and bc.code = 'carryForward'

    and bv.year_period >= #{startPeriod}


    and bv.year_period <= #{endPeriod}
